import 'package:decimal/decimal.dart';
import 'package:finance_tracker/domain/entities/transaction.dart';

/// The two linked rows of one transfer between the user's own accounts
/// (docs/05_FINANCIAL_LOGIC.md): a `transfer_out` on the source account and a
/// `transfer_in` on the destination, sharing one transfer id and amount. A
/// transfer moves money but never changes the total balance.
class TransferLegs {
  const TransferLegs({required this.outgoing, required this.incoming});

  /// Builds both legs of a transfer. Ids are generated by the caller once per
  /// form, so a retried save upserts the same rows.
  ///
  /// Throws [ArgumentError] when the accounts are the same or the amount is
  /// not positive; the form validates both first.
  factory TransferLegs.build({
    required String transferId,
    required String outgoingId,
    required String incomingId,
    required String fromAccountId,
    required String toAccountId,
    required Decimal amount,
    required DateTime date,
    required DateTime now,
    String? note,
    String userId = '',
    DateTime? createdAt,
  }) {
    if (fromAccountId == toAccountId) {
      throw ArgumentError.value(
        toAccountId,
        'toAccountId',
        'must differ from the source account',
      );
    }
    if (amount <= Decimal.zero) {
      throw ArgumentError.value(amount, 'amount', 'must be positive');
    }
    Transaction leg(String id, String accountId, TransactionType type) =>
        Transaction(
          id: id,
          userId: userId,
          accountId: accountId,
          type: type,
          amount: amount,
          transactionDate: date,
          note: note,
          transferId: transferId,
          createdAt: createdAt ?? now,
          updatedAt: now,
        );
    return TransferLegs(
      outgoing: leg(outgoingId, fromAccountId, TransactionType.transfer_out),
      incoming: leg(incomingId, toAccountId, TransactionType.transfer_in),
    );
  }

  /// `transfer_out` on the source account.
  final Transaction outgoing;

  /// `transfer_in` on the destination account.
  final Transaction incoming;

  String get transferId => outgoing.transferId!;
  String get fromAccountId => outgoing.accountId;
  String get toAccountId => incoming.accountId;
  Decimal get amount => outgoing.amount;
  DateTime get date => outgoing.transactionDate;
  String? get note => outgoing.note;

  static bool isLeg(Transaction t) =>
      t.transferId != null &&
      (t.type == TransactionType.transfer_out ||
          t.type == TransactionType.transfer_in);

  /// Pairs the live legs among [rows]; null unless there is exactly one
  /// outgoing and one incoming leg of the same transfer.
  static TransferLegs? fromRows(Iterable<Transaction> rows) {
    final List<Transaction> live = rows
        .where((Transaction t) => t.deletedAt == null && isLeg(t))
        .toList();
    if (live.length != 2) return null;
    final Iterable<Transaction> out = live.where(
      (Transaction t) => t.type == TransactionType.transfer_out,
    );
    final Iterable<Transaction> into = live.where(
      (Transaction t) => t.type == TransactionType.transfer_in,
    );
    if (out.length != 1 || into.length != 1) return null;
    if (out.first.transferId != into.first.transferId) return null;
    return TransferLegs(outgoing: out.first, incoming: into.first);
  }

  /// Whether an edit to [newFromAccountId] can update the existing rows in
  /// place. The server allows one leg per account per transfer, and the two
  /// updates sync one after the other (outgoing first), so moving the
  /// outgoing leg onto the account the incoming leg still holds would be
  /// rejected half-way. That edit replaces the transfer with new rows.
  bool canUpdateInPlace(String newFromAccountId) =>
      newFromAccountId != toAccountId;
}
